    const courier = await prisma.courier.create({ data: { displayName: 'María' } });
    const patch = (token, path, body) => fetch(`${origin}/api/${path}`, { method: 'PATCH', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
