    assert.equal((await patch('http-admin', `couriers/${courier.id}/user`, { userId: 'http-operator', expectedUserId: null })).status, 409);
    assert.equal((await patch('http-admin', `couriers/${courier.id}/user`, { userId: 'http-courier', expectedUserId: null })).status, 200);
    assert.equal((await patch('http-admin', `couriers/${courier.id}/user`, { userId: null, expectedUserId: null })).status, 409);
